inline void score_service_rf(double* input, double* output) {
 output[0]=output[1]=output[2]=0.0;
 for(int root : scada_compact_rf::roots) {
  int i=root;
  while(scada_compact_rf::nodes[i].left>=0) {
   const auto& n=scada_compact_rf::nodes[i];
   i=static_cast<float>(input[n.feature])<=n.threshold ? n.left : n.right;
  }
  const auto& n=scada_compact_rf::nodes[i];
  for(int c=0;c<3;++c) output[c]+=n.p[c];
 }
 for(int c=0;c<3;++c) output[c]/=100.0;
}
